package com.sneha.snehamart.dao;import com.zaxxer.hikari.HikariDataSource;import java.sql.*;import java.util.*;
/** JDBC data-access helpers. SQL is parameterized and resources are scoped with try-with-resources. */
public final class JdbcDAO implements OrderRepository {private final HikariDataSource ds;public JdbcDAO(HikariDataSource ds){this.ds=ds;}public Map<String,Object> placeOrder(long userId)throws SQLException{try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{List<long[]>items=new ArrayList<>();java.math.BigDecimal total=java.math.BigDecimal.ZERO;try(PreparedStatement p=c.prepareStatement("SELECT c.product_id,c.quantity,p.price,p.stock_qty FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=? FOR UPDATE")){p.setLong(1,userId);try(ResultSet r=p.executeQuery()){while(r.next()){long id=r.getLong(1);int qty=r.getInt(2);if(qty>r.getInt(4))throw new IllegalArgumentException("A little item is low in stock. Please update your bag.");total=total.add(r.getBigDecimal(3).multiply(java.math.BigDecimal.valueOf(qty)));items.add(new long[]{id,qty});}}}if(items.isEmpty())throw new IllegalArgumentException("Your bag is empty.");long orderId;try(PreparedStatement p=c.prepareStatement("INSERT INTO orders(buyer_id,status,total_amount) VALUES(?,'CONFIRMED',?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,userId);p.setBigDecimal(2,total);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();orderId=r.getLong(1);}}for(long[]item:items){try(PreparedStatement p=c.prepareStatement("INSERT INTO order_items(order_id,product_id,quantity,unit_price) SELECT ?,id,?,price FROM products WHERE id=?")){p.setLong(1,orderId);p.setLong(2,item[1]);p.setLong(3,item[0]);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE products SET stock_qty=stock_qty-? WHERE id=?")){p.setLong(1,item[1]);p.setLong(2,item[0]);p.executeUpdate();}}try(PreparedStatement p=c.prepareStatement("DELETE FROM cart_items WHERE user_id=?")){p.setLong(1,userId);p.executeUpdate();}c.commit();Map<String,Object>result=new LinkedHashMap<>();result.put("id",orderId);result.put("totalAmount",total);result.put("status","CONFIRMED");return result;}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}private Map<String,Object> row(ResultSet r)throws SQLException{ResultSetMetaData m=r.getMetaData();Map<String,Object>x=new LinkedHashMap<>();for(int i=1;i<=m.getColumnCount();i++){String label=m.getColumnLabel(i).toLowerCase(Locale.ROOT);StringBuilder key=new StringBuilder();boolean upper=false;for(char ch:label.toCharArray()){if(ch=='_')upper=true;else{key.append(upper?Character.toUpperCase(ch):ch);upper=false;}}x.put(key.toString(),r.getObject(i));}return x;}public List<Map<String,Object>> query(String sql,Object...args)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);try(ResultSet r=p.executeQuery()){List<Map<String,Object>>a=new ArrayList<>();while(r.next())a.add(row(r));return a;}}}public int update(String sql,Object...args)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p.executeUpdate();}}public long insert(String sql,Object...args)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getLong(1);}}throw new SQLException("No generated key");}}